def save(p,d):
 f=HERE/p; f.parent.mkdir(parents=True,exist_ok=True); f.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
def source(label,url):return dict(label=label,url=url)
def readable(x,key=''):
 if isinstance(x,dict):return {k:readable(v,k) for k,v in x.items()}
 if isinstance(x,list):return [readable(v,key) for v in x]
 if not isinstance(x,str) or key in {'id','code','protocol_id','protocol_version','phase_id','source_ids','phase_ids','agents','active_medicines','script_id','source_url','url','route','endpoint'} or x.startswith(('https:','nccp-')):return x
 x=re.sub(r'(?<=[A-Za-z])(?=\d)|(?<=\d)(?=[A-Za-z])',' ',x)
 x=re.sub(r'(?<=[a-z])(?=[A-Z])',' ',x)
 x=re.sub(r'([;,])(?=\S)',r'\1 ',x)
 for wrong,right in [('BRCA 1','BRCA1'),('BRCA 2','BRCA2'),('HER 2','HER2'),('CYP 3 A','CYP3A'),('m L','mL'),('Na Cl','NaCl'),('Sm PC','SmPC'),('p CR','pCR'),('i DFS','iDFS'),('Olympi A','OlympiA'),('evi Q','eviQ'),('%CI','% CI')]:x=x.replace(wrong,right)
 x=x.replace('8 and 15','8 and 15').replace('NCCP 0','NCCP 0')
 return x
N={x['id']:x for x in json.loads((HERE/'sources.json').read_text())}
